// Identifier types shared by the API, the CLI and the web client. Every
// identifier is a UUID generated by the application; the brand keeps one kind
// of identifier from being passed where another is expected.
import { z } from "zod";

export const organizationIdSchema = z.uuid().brand<"OrganizationId">();
export const projectIdSchema = z.uuid().brand<"ProjectId">();
export const environmentIdSchema = z.uuid().brand<"EnvironmentId">();
export const credentialIdSchema = z.uuid().brand<"CredentialId">();
export const operationIdSchema = z.uuid().brand<"OperationId">();
export const userIdSchema = z.uuid().brand<"UserId">();
export const requestIdSchema = z.uuid().brand<"RequestId">();

export type OrganizationId = z.infer<typeof organizationIdSchema>;
export type ProjectId = z.infer<typeof projectIdSchema>;
export type EnvironmentId = z.infer<typeof environmentIdSchema>;
export type CredentialId = z.infer<typeof credentialIdSchema>;
export type OperationId = z.infer<typeof operationIdSchema>;
export type UserId = z.infer<typeof userIdSchema>;
export type RequestId = z.infer<typeof requestIdSchema>;
